\section*{ Derivation of Eq.~(16)}  

Writing the illustration depicted in Fig.3 as an algebraic expression yields:  
\begin{eqnarray}  
\nn  
\langle j_3 j_3 \rangle &\sim& {\rm tr}\Big[M\sigma^{}_3[\partial^{}_\tau\sigma^{}_0 + i\partial^{}_\nu\sigma^{}_{\nu=1,2}]^{-1}\Big]^2 \\  
&=&  
\int\frac{d^3P}{(2\pi)^3}M_{P} M_{-P}  
\underbrace{{\rm Tr}~\int\frac{d^3K}{(2\pi)^3}\frac{\sigma^{}_3[ik^{}_0\sigma^{}_0+k^{}_\nu\sigma^{}_\nu]\sigma^{}_3[i(k^{}_0+p^{}_0)\sigma^{}_0+(k^{}_\mu+p^{}_\mu)\sigma^{}_\mu]}{K^2(K+P)^2}}_{=\Pi^{-1}_{33}(P)}  
\end{eqnarray}  
where $K^2=k^2_0+\bk^2$. With the Feynman method  
\begin{equation}  
\frac{1}{AB}=\intop_0^1~\frac{dx}{[(1-x)A+xB]^2},  
\end{equation}  
follows  
\begin{equation}  
\Pi^{-1}_{33} (P) = {\rm Tr}\int_0^1 dx~\int\frac{d^3K}{(2\pi)^3}\frac{[ik^{}_0\sigma^{}_0-k^{}_\nu\sigma^{}_\nu][i(k^{}_0+p^{}_0)\sigma^{}_0+(k^{}_\mu+p^{}_\mu)\sigma^{}_\mu]}{[(1-x)K^2+x(K+P)^2]^2},  
\end{equation}  
where the sign alteration in the first term is because $\sigma^{}_\nu$ anticommutes with $\sigma^{}_3$. Shifting $k^{}_{i=0,1,2}\to k^{}_i - x p^{}_i$, performing the trace and keeping only rotationally invariant terms yields  
\begin{equation}  
\Pi^{-1}_{33} (P) = 2\int_0^1 dx~\int\frac{d^3K}{(2\pi)^3}\frac{x(1-x)P^2 - K^2}{[K^2+x(1-x)P^2]^2}.  
\end{equation}  
Using formulas of dimensional regularization  
\begin{eqnarray}  
\label{eq:DimReg}  
\intop\frac{d^dK}{(2\pi)^d} \frac{1}{(K^2+\Delta)^n} &=& \frac{1}{(4\pi)^{d/2}}  
\frac{\Gamma(n-\frac{d}{2})}{\Gamma(n)\Delta^{n-{d/2}}}, \\  
\nonumber  
\intop\frac{d^dK}{(2\pi)^d} \frac{K^2}{(K^2+\Delta)^n} &=& \frac{1}{(4\pi)^{d/2}}\frac{d}{2} \frac{\Gamma(n-\frac{d}{2}-1)}{\Gamma(n)\Delta^{n-{d/2}-1}},  
\end{eqnarray}  
yields  
\begin{equation}  
\Pi^{-1}_{33} (P) = \frac{1}{\pi}|P|\int_0^1 dx \sqrt{x(1-x)} = \frac{1}{8}\sqrt{p^2_0+\bp^2},  
\end{equation}  
where the integration over $x$ is carried out with the substitution $x=\sin^2\alpha$, giving  
\begin{equation}  
\int_0^1 dx~\sqrt{x(1-x)} = \int^{\pi/2}_{0}d\alpha~\sin^2\alpha\cos^2\alpha=\frac{\pi}{8}.  
\end{equation}  

