\section*{Appendix}\label{sec:App}
\begin{lemma}\label{lem:Trees}
For a finite extension $\Field{E}/\Field{F}$ there is a topological embedding of trees $\Tree_{\Field{F}}\hookrightarrow\Tree_{\Field{E}}$, induced by tensoring lattices in $\Field{F}\times\Field{F}$ with $\oRing{\Field{E}}$ with these characteristics:
\begin{enumerate}[i.]
\item  As a map of metric spaces under the graph metric, this embedding has a constant dilation factor of $\ramInd{\Field{E}/\Field{F}}$,
\item the natural operation of $\GL{2}{\Field{F}}$ on $\Tree_{\Field{F}}$ extends to the natural operation of $\GL{2}{\Field{F}}$ on $\Tree_{\Field{E}}$ as a subgroup of $\GL{2}{\Field{E}}$, and
\item the Galois operation on $\Tree_{\Field{E}}$ is isometric, and stabilizes at least the image $\Tree_{\Field{F}}$.
\end{enumerate}
\end{lemma}

