\section*{Appendix}

We here demonstrate that
\begin{equation}
  \label{eq:tobeproven}
  \Bigl(\bigl({\bf M}^{-1}\bigr)_{AA}\Bigr)^{-1} = {\bf M}_{AA} -
  {\bf M}_{AB} \bigl({\bf M}_{BB}\bigr)^{-1} {\bf M}_{BA}
\end{equation}
Demonstration: Let ${\bf N} = {\bf M}^{-1}$.  We then have ${\bf MN} = {\bf
  1}$, which can be divided into four parts:
\begin{mathletters}
  \begin{eqnarray}
    {\bf M}_{AA} {\bf N}_{AA} + {\bf M}_{AB} {\bf N}_{BA} & = & {\bf 1}
    \label{eq:partAA}, \\
    {\bf M}_{AA} {\bf N}_{AB} + {\bf M}_{AB} {\bf N}_{BB} & = & {\bf 0}
    \label{eq:partAB}, \\
    {\bf M}_{BA} {\bf N}_{AA} + {\bf M}_{BB} {\bf N}_{BA} & = & {\bf 0}
    \label{eq:partBA}, \\
    {\bf M}_{BB} {\bf N}_{BB} + {\bf M}_{BB} {\bf N}_{BB} & = & {\bf 1}
    \label{eq:partBB}.
  \end{eqnarray}
\end{mathletters}
From (\ref{eq:partBA}) we obtain
\begin{equation}
  {\bf N}_{BA} = - \bigl( {\bf M}_{BB} \bigr)^{-1} {\bf M}_{BA} {\bf
